using System.Windows;
using System.Windows.Controls;
using SysAdminAssistant.Core;
using SysAdminAssistant.Infrastructure;
namespace SysAdminAssistant.Desktop;
public partial class MainWindow
{
 private async Task AgentEventsWindow(Device device,Window owner,bool linux){var window=new DialogWindow{Owner=owner,Title=(linux?"Журналы Linux · ":"Журналы Windows · ")+device.Name,Width=1050,Height=650,WindowStartupLocation=WindowStartupLocation.CenterOwner};var tabs=new TabControl();var bar=new WrapPanel();var root=new DockPanel();DockPanel.SetDock(bar,Dock.Top);root.Children.Add(bar);root.Children.Add(tabs);window.Content=root;AgentEventState state=new();DataGrid? problems=null;bool busy=false;
 async Task Refresh(){state=await remote.CommandAsync<AgentEventState>("agent-events",new AgentEventsRequest(device.Id),lifetime.Token);tabs.Items.Clear();
 problems=Table(state.Problems.Where(p=>p.Open).OrderByDescending(p=>p.Severity).ToArray(),("Событие","Title",null),("Уровень","Severity",null),("Последнее событие","LastUtc","dd.MM HH:mm:ss"),("Повторы","Count",null));problems.SetValue(HasCustomDoubleClickProperty,true);problems.MouseDoubleClick+=(_,_)=>{if(problems.SelectedItem is AgentEventProblem problem)new FormDialog(window,problem.Title,950).Text("details","Причина, факты и рекомендации",AgentEventExplanation.Describe(state,problem),true,true).TextHeight("details",480).ViewOnly().ShowDialog();};tabs.Items.Add(new TabItem{Header="Открытые проблемы",Content=TableSurface(problems)});
 var pastProblems=Table(state.Problems.OrderByDescending(p=>p.LastUtc).ToArray(),("Проблема","Title",null),("Активно","Open",null),("Закрыто","ClosedUtc","dd.MM HH:mm:ss"),("Причина закрытия","Resolution",null));pastProblems.SetValue(HasCustomDoubleClickProperty,true);pastProblems.MouseDoubleClick+=(_,_)=>{if(pastProblems.SelectedItem is AgentEventProblem problem)new FormDialog(window,problem.Title,950).Text("details","Причина, факты и рекомендации",AgentEventExplanation.Describe(state,problem),true,true).TextHeight("details",480).ViewOnly().ShowDialog();};tabs.Items.Add(new TabItem{Header="История проблем",Content=TableSurface(pastProblems)});
 var events=Table(state.Events.AsEnumerable().Reverse().ToArray(),("Время сервера","TimeUtc","dd.MM HH:mm:ss"),("Журнал","Channel",null),("Поставщик событий","Provider",null),("ID","Id",null),("Событие","Message",null));events.SetValue(HasCustomDoubleClickProperty,true);events.MouseDoubleClick+=(_,_)=>{if(events.SelectedItem is AgentJournalEvent e)new FormDialog(window,"Событие журнала",950).Text("details","Исходное событие и рекомендации",AgentEventExplanation.DescribeEvent(state,e),true,true).TextHeight("details",480).ViewOnly().ShowDialog();};tabs.Items.Add(new TabItem{Header="История событий",Content=TableSurface(events)});
 tabs.Items.Add(new TabItem{Header="Состояние чтения",Content=TableSurface(Table(state.Health,("Журнал","Channel",null),("Состояние","State",null),("Подробности","Detail",null)))});
 }
 void Button(string title,Func<Task> action,bool edit=false){var b=UiButton(title);b.IsEnabled=!edit||AccessRules.Level(remote.CurrentUser,"devices")>=2;b.Click+=async(_,_)=>{if(busy)return;busy=true;bar.IsEnabled=false;try{await action();}catch(Exception e){AppMessageBox.Show(window,e.Message,"Журналы",MessageBoxButton.OK,MessageBoxImage.Error);}finally{bar.IsEnabled=true;busy=false;}};bar.Children.Add(b);}
 Button("Обновить",Refresh);Button("Полная история журнала",()=>AgentJournalHistoryWindow(device.Id,state,window));Button("Подробности",()=>{if(problems?.SelectedItem is AgentEventProblem problem)new FormDialog(window,problem.Title,950).Text("details","Причина, факты и рекомендации",AgentEventExplanation.Describe(state,problem),true,true).TextHeight("details",480).ViewOnly().ShowDialog();return Task.CompletedTask;});Button("Решено",async()=>{if(problems?.SelectedItem is AgentEventProblem p){await remote.CommandAsync<bool>("agent-event-resolve",new AgentEventResolve(device.Id,p.Id),lifetime.Token);await Refresh();}},true);Button("Правила и обновления ОС",async()=>{await AgentEventRules(device.Id,state.Policy,window,linux);await Refresh();},true);await Refresh();window.ShowDialog();}
 private async Task AgentEventRules(int id,AgentEventPolicy original,Window owner,bool linux){var p=Copy(original);var window=new DialogWindow{Owner=owner,Title=linux?"Правила журналов Linux":"Правила журналов Windows",Width=1050,Height=650,WindowStartupLocation=WindowStartupLocation.CenterOwner};var table=Table(p.Rules,("Правило","Name",null),("Включено","Enabled",null),("Журнал","Channel",null),("Поставщик событий","Provider",null),("Уровень","Severity",null),("Порог","Threshold",null));var bar=new WrapPanel();var root=new DockPanel();DockPanel.SetDock(bar,Dock.Top);root.Children.Add(bar);root.Children.Add(table);window.Content=root;bool busy=false;
 async Task Save(){AgentEvents.Validate(p);p=await remote.CommandAsync<AgentEventPolicy>("agent-events-save",new AgentEventsSave(id,p,p.Version),lifetime.Token);table.ItemsSource=p.Rules.ToArray();}
 void Button(string title,Func<Task> action){var b=UiButton(title);b.Click+=async(_,_)=>{if(busy)return;busy=true;bar.IsEnabled=false;try{await action();}catch(Exception e){AppMessageBox.Show(window,e.Message);}finally{busy=false;bar.IsEnabled=true;}};bar.Children.Add(b);}
 async Task Edit(AgentEventRule? old){var rule=old==null?new AgentEventRule{Channel=linux?"Linux":"System",Provider=linux?"journald":""}:Copy(old);var f=new FormDialog(window,"Правило события").Text("name","Название",rule.Name).Toggle("enabled","Контролировать",rule.Enabled).Select("channel","Журнал",AgentEvents.Channels.Where(c=>linux?c=="Linux":c!="Linux").Select(c=>new Choice(c,c)),rule.Channel).Text("provider","Точный источник (Provider)",rule.Provider).Text("ids","ID событий через запятую",string.Join(",",rule.Ids)).Text("contains","Текст содержит · необязательно",rule.Contains).Select("severity","Важность",new[]{new Choice(Severity.Info,"Информация"),new Choice(Severity.Warning,"Предупреждение"),new Choice(Severity.Critical,"Критично")},rule.Severity).Text("count","Порог количества событий",rule.Threshold.ToString()).Text("critical","Критично при количестве · 0 отключает",rule.CriticalThreshold.ToString()).Text("window","Окно подсчёта, минут",rule.WindowMinutes.ToString()).Text("quiet","Закрыть после тишины, минут · 0 = вручную",rule.QuietMinutes.ToString()).Toggle("notify","Уведомлять через Telegram",rule.Notify);
 void Read(){rule.Name=f.Value("name");rule.Enabled=f.Checked("enabled");rule.Channel=f.Selected<string>("channel");rule.Provider=f.Value("provider");rule.Ids=f.Value("ids").Split(',',StringSplitOptions.TrimEntries|StringSplitOptions.RemoveEmptyEntries).Select(int.Parse).Distinct().ToArray();rule.Contains=f.Value("contains");rule.Severity=f.Selected<Severity>("severity");rule.Threshold=f.Number("count",1,10000);rule.CriticalThreshold=f.Number("critical",0,100000);rule.WindowMinutes=f.Number("window",1,1440);rule.QuietMinutes=f.Number("quiet",0,1440);rule.Notify=f.Checked("notify");AgentEvents.Validate(new AgentEventPolicy{Rules=[rule]});}f.Validate=()=>{Read();return null;};if(f.ShowDialog()!=true)return;Read();if(old!=null)p.Rules.RemoveAll(r=>r.Id==old.Id);p.Rules.Add(rule);await Save();}
 Button("Добавить",()=>Edit(null));Button("Изменить",async()=>{if(table.SelectedItem is AgentEventRule rule)await Edit(rule);});Button("Удалить",async()=>{if(table.SelectedItem is AgentEventRule rule&&Confirm(window,"Удалить правило «"+rule.Name+"»?")){p.Rules.RemoveAll(r=>r.Id==rule.Id);await Save();}});
 foreach(var role in linux?Array.Empty<string>():new[]{"SQL","AD","DNS"})Button("Добавить "+role,async()=>{foreach(var rule in AgentEvents.Role(role))if(!p.Rules.Any(r=>r.Id==rule.Id))p.Rules.Add(rule);await Save();});
 Button("Сбор",async()=>{var f=new FormDialog(window,"Сбор данных").Toggle("enabled",linux?"Читать системный журнал Linux":"Читать журналы Windows",p.Enabled).Toggle("updates",linux?"Читать локальный кэш обновлений APT":"Читать локальный кэш обновлений Windows",p.Updates).Note("Агент не запускает поиск, загрузку и установку обновлений. Старые записи при первом подключении не собираются. О наличии обновлений Telegram не уведомляет. Реальные ошибки установки учитываются как события журнала.");if(f.ShowDialog()==true){p.Enabled=f.Checked("enabled");p.Updates=f.Checked("updates");await Save();}});window.ShowDialog();}
}
